import * as T from './vendor/three.js';
import {makeTextures} from './textures.js';
const read=async(url,type)=>{const r=await fetch(url);if(!r.ok)throw Error(`Could not load ${url}`);return new type(await r.arrayBuffer())};
export async function loadWorld(scene){
 const [meta,coarse,fine,buildings,roofData,wallData,map,roofImagery]=await Promise.all([fetch('./geodata.json').then(r=>r.json()),read('./terrain.bin',Int32Array),read('./terrain-fine.bin',Int32Array),fetch('./buildings.json').then(r=>r.json()),read('./building-roofs.bin',Float32Array),read('./building-walls.bin',Float32Array),fetch('./map.json').then(r=>r.json()),fetch('./roof-imagery.json').then(r=>r.json())]);
 const aerialTexture=await new T.TextureLoader().loadAsync('./'+roofImagery.image);aerialTexture.colorSpace=T.SRGBColorSpace;aerialTexture.magFilter=T.NearestFilter;aerialTexture.minFilter=T.LinearMipmapLinearFilter;aerialTexture.anisotropy=4;
 const datum=meta.originElevation,textures=makeTextures(),windowMaterials=[],photoMaterials=[];
 function sample(a,g,x,z){let u=T.MathUtils.clamp((x-g.minX)/g.step,0,g.width-1.000001),v=T.MathUtils.clamp((z-g.minZ)/g.step,0,g.height-1.000001),i=Math.floor(u),j=Math.floor(v),du=u-i,dv=v-j,k=j*g.width+i;return(du+dv<=1?a[k]+du*(a[k+1]-a[k])+dv*(a[k+g.width]-a[k]):a[k+g.width+1]+(1-du)*(a[k+g.width]-a[k+g.width+1])+(1-dv)*(a[k+1]-a[k+g.width+1]))/100-datum}
 const coarseGrid={...meta.terrain,width:meta.terrain.size,height:meta.terrain.size};
 const coarseHeight=(x,z)=>sample(coarse,coarseGrid,x,z);
 function ground(x,z){let f=meta.fine;if(x<f.minX||z<f.minZ||x>f.minX+(f.width-1)*f.step||z>f.minZ+(f.height-1)*f.step)return coarseHeight(x,z);const edge=Math.min(x-f.minX,z-f.minZ,f.minX+(f.width-1)*f.step-x,f.minZ+(f.height-1)*f.step-z);return T.MathUtils.lerp(coarseHeight(x,z),sample(fine,f,x,z),Math.min(1,edge/20))}
 function terrainMesh(grid,step,skipCentre=false){const width=Math.round((grid.width-1)*grid.step/step)+1,height=Math.round((grid.height-1)*grid.step/step)+1;const positions=new Float32Array(width*height*3),colors=new Float32Array(width*height*3),indices=[];const col=new T.Color();for(let j=0;j<height;j++)for(let i=0;i<width;i++){let x=grid.minX+i*step,z=grid.minZ+j*step,y=ground(x,z),k=(j*width+i)*3;positions.set([x,y,z],k);const slope=Math.hypot(ground(x+4,z)-ground(x-4,z),ground(x,z+4)-ground(x,z-4))/8;col.set(slope>.4?'#9fbbab':y>140?'#b4ccb2':'#f4fff1');colors.set([col.r,col.g,col.b],k);if(i<width-1&&j<height-1){const f=meta.fine;if(skipCentre&&x>=f.minX&&z>=f.minZ&&x+step<=f.minX+(f.width-1)*f.step&&z+step<=f.minZ+(f.height-1)*f.step)continue;let a=j*width+i;indices.push(a,a+width,a+1,a+1,a+width,a+width+1)}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(positions,3));geo.setAttribute('color',new T.BufferAttribute(colors,3));const uvs=new Float32Array(width*height*2);for(let j=0;j<height;j++)for(let i=0;i<width;i++){let k=(j*width+i)*2;uvs[k]=(grid.minX+i*step)/8;uvs[k+1]=(grid.minZ+j*step)/8}geo.setAttribute('uv',new T.BufferAttribute(uvs,2));geo.setIndex(indices);geo.computeVertexNormals();const mesh=new T.Mesh(geo,new T.MeshLambertMaterial({vertexColors:true,map:textures.grass}));scene.add(mesh)}
 terrainMesh(coarseGrid,20,true);terrainMesh(meta.fine,2);
 // Keep the surveyed meshes intact; vary only their surface appearance.
 const paintPalette=['#eef1f1','#d1e1ec','#bcdad1','#e2e7eb','#d1d9e0','#e7d9cd','#afd0d9','#eedddd'];
 const buildingCells=new Map();for(const b of buildings){const r=b.rings[0];b.paintBounds=[Math.min(...r.map(v=>v[0])),Math.min(...r.map(v=>v[1])),Math.max(...r.map(v=>v[0])),Math.max(...r.map(v=>v[1]))];b.style=b.id%4;b.paint=new T.Color(paintPalette[b.id%paintPalette.length]);b.roofPaint=new T.Color('#ffffff');for(let x=Math.floor(b.paintBounds[0]/30);x<=Math.floor(b.paintBounds[2]/30);x++)for(let z=Math.floor(b.paintBounds[1]/30);z<=Math.floor(b.paintBounds[3]/30);z++){const key=x+','+z;if(!buildingCells.has(key))buildingCells.set(key,[]);buildingCells.get(key).push(b)}}
 const contains=(b,x,z)=>{const r=b.paintBounds;if(x<r[0]-.04||z<r[1]-.04||x>r[2]+.04||z>r[3]+.04)return false;for(const ring of b.rings)for(let i=1;i<ring.length;i++){const a=ring[i-1],c=ring[i],dx=c[0]-a[0],dz=c[1]-a[1],t=T.MathUtils.clamp(((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz||1),0,1);if(Math.hypot(x-a[0]-t*dx,z-a[1]-t*dz)<.04)return true}return inside(b.rings[0],x,z)&&!b.rings.slice(1).some(r=>inside(r,x,z))};
 function buildingMesh(data,roof=false){let previous=null;const buckets=Array.from({length:roof?1:4},()=>({positions:[],uvs:[],colors:[]}));for(let i=0;i<data.length;i+=9){const x=(data[i]+data[i+3]+data[i+6])/3,z=(data[i+2]+data[i+5]+data[i+8])/3;let b=previous&&contains(previous,x,z)?previous:(buildingCells.get(Math.floor(x/30)+','+Math.floor(z/30))||[]).find(b=>contains(b,x,z));previous=b;const bucket=buckets[roof?0:(b?.style||0)],paint=b?(roof?b.roofPaint:b.paint):new T.Color('#d5e2e6');const dx=data[i+3]-data[i],dz=data[i+5]-data[i+2],dx2=data[i+6]-data[i],dz2=data[i+8]-data[i+2];const tx=Math.abs(dx)+Math.abs(dz)>.01?dx:dx2,tz=Math.abs(dx)+Math.abs(dz)>.01?dz:dz2,length=Math.hypot(tx,tz)||1;for(let j=0;j<9;j+=3){const px=data[i+j],py=data[i+j+1],pz=data[i+j+2];bucket.positions.push(px,py,pz);bucket.uvs.push(roof?(px-roofImagery.minX)/(roofImagery.maxX-roofImagery.minX):(px*tx/length+pz*tz/length)/7,roof?(roofImagery.maxZ-pz)/(roofImagery.maxZ-roofImagery.minZ):1-(py-(b?b.ground-datum:0))/3.4);let shade=roof?1:T.MathUtils.lerp(.8,1,Math.min(1,Math.max(0,(py-(b?b.ground-datum:0))/1.8)));bucket.colors.push(paint.r*shade,paint.g*shade,paint.b*shade)}}for(let i=0;i<buckets.length;i++){const b=buckets[i];if(!b.positions.length)continue;const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(b.positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(b.uvs,2));g.setAttribute('color',new T.Float32BufferAttribute(b.colors,3));g.computeVertexNormals();const material=roof?new T.MeshBasicMaterial({map:aerialTexture,side:T.DoubleSide}):new T.MeshLambertMaterial({map:textures.walls[i],emissive:'#ffc987',emissiveMap:textures.windowMasks[i],emissiveIntensity:0,vertexColors:true,side:T.DoubleSide});if(roof)photoMaterials.push(material);else windowMaterials.push(material);scene.add(new T.Mesh(g,material))}}
 buildingMesh(wallData);buildingMesh(roofData,true);
 const roads=map.elements.map(el=>({p:el.geometry.map(p=>new T.Vector2(p.x,p.z)),name:el.tags.name||'',type:el.tags.highway,width:['primary','secondary','tertiary'].includes(el.tags.highway)?11:['footway','path','cycleway','steps'].includes(el.tags.highway)?1.8:el.tags.highway==='service'?4:7}));
 const strips={road:[],pavement:[],line:[]};
 function strip(a,b,width,offset,key){const dx=b.x-a.x,dz=b.y-a.y,len=Math.hypot(dx,dz);if(len<.001)return;const nx=dz/len,nz=-dx/len,n=Math.max(1,Math.ceil(len/1.5)),across=Math.max(1,Math.ceil(width/1.5));for(let k=0;k<n;k++){let a1=a.clone().lerp(b,k/n),b1=a.clone().lerp(b,(k+1)/n);for(let j=0;j<across;j++){let l=-width/2+j*width/across,r=-width/2+(j+1)*width/across;const p=[[a1.x+nx*l,a1.y+nz*l],[a1.x+nx*r,a1.y+nz*r],[b1.x+nx*r,b1.y+nz*r],[b1.x+nx*l,b1.y+nz*l]];for(const i of [0,2,1,0,3,2]){const [x,z]=p[i];strips[key].push(x,ground(x,z)+offset,z)}}}}

 for(const r of roads)for(let i=1;i<r.p.length;i++){const a=r.p[i-1],b=r.p[i];strip(a,b,r.width+2.5,.07,'pavement');strip(a,b,r.width,.11,'road');if(r.width>6){const len=a.distanceTo(b);for(let j=3;j<len;j+=14)strip(a.clone().lerp(b,j/len),a.clone().lerp(b,Math.min((j+4)/len,1)),.12,.145,'line')}}
 for(const key of ['pavement','road','line']){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(strips[key],3));const surfaceUV=new Float32Array(strips[key].length/3*2);for(let i=0,j=0;i<strips[key].length;i+=3,j+=2){surfaceUV[j]=strips[key][i]/(key==='road'?5:4);surfaceUV[j+1]=strips[key][i+2]/(key==='road'?5:4)}g.setAttribute('uv',new T.BufferAttribute(surfaceUV,2));g.computeVertexNormals();scene.add(new T.Mesh(g,new T.MeshLambertMaterial({color:key==='line'?'#f5f2db':'#ffffff',map:key==='road'?textures.asphalt:key==='pavement'?textures.concrete:null,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:key==='line'?-4:key==='road'?-3:-2,polygonOffsetUnits:-2})))}
 function nearest(x,z){let best=Infinity,name='Wainuiomata';for(const r of roads){for(let i=1;i<r.p.length;i++){const a=r.p[i-1],b=r.p[i],vx=b.x-a.x,vz=b.y-a.y,len=vx*vx+vz*vz;if(!len)continue;const t=T.MathUtils.clamp(((x-a.x)*vx+(z-a.y)*vz)/len,0,1),d=Math.hypot(a.x+t*vx-x,a.y+t*vz-z);if(d<best){best=d;name=r.name||'Wainuiomata'}}}return{d:best,name}}
 const cells=new Map();for(const b of buildings){let r=b.rings[0];b.minX=Math.min(...r.map(p=>p[0]));b.maxX=Math.max(...r.map(p=>p[0]));b.minZ=Math.min(...r.map(p=>p[1]));b.maxZ=Math.max(...r.map(p=>p[1]));for(let i=Math.floor((b.minX-1)/25);i<=Math.floor((b.maxX+1)/25);i++)for(let j=Math.floor((b.minZ-1)/25);j<=Math.floor((b.maxZ+1)/25);j++){let key=i+','+j;if(!cells.has(key))cells.set(key,[]);cells.get(key).push(b)}}
 function inside(r,x,z){let found=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const [xi,zi]=r[i],[xj,zj]=r[j];if((zi>z)!==(zj>z)&&x<(xj-xi)*(z-zi)/(zj-zi)+xi)found=!found}return found}
 function free(x,z){for(const b of cells.get(Math.floor(x/25)+','+Math.floor(z/25))||[]){if(inside(b.rings[0],x,z)&&!b.rings.slice(1).some(r=>inside(r,x,z)))return false;for(const r of b.rings)for(let i=1;i<r.length;i++){const a=r[i-1],c=r[i],dx=c[0]-a[0],dz=c[1]-a[1],t=T.MathUtils.clamp(((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz||1),0,1);if(Math.hypot(x-a[0]-t*dx,z-a[1]-t*dz)<.35)return false}}return true}
 // Decorative vegetation only; all terrain and building geometry remains measured.
 let seed=91;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};const trunkGeo=new T.CylinderGeometry(.25,.4,4,5),leafGeo=new T.ConeGeometry(3.3,8,5),trunk=new T.InstancedMesh(trunkGeo,new T.MeshLambertMaterial({color:'#73675e'}),240),leaves=new T.InstancedMesh(leafGeo,new T.MeshLambertMaterial({color:'#368251'}),240);let n=0;const dummy=new T.Object3D();for(let i=0;i<900&&n<240;i++){const x=(rand()-.5)*2600,z=(rand()-.5)*2600;if(nearest(x,z).d<24||!free(x,z))continue;const y=ground(x,z);dummy.position.set(x,y+2,z);dummy.updateMatrix();trunk.setMatrixAt(n,dummy.matrix);dummy.position.y=y+7;dummy.updateMatrix();leaves.setMatrixAt(n++,dummy.matrix)}trunk.count=leaves.count=n;scene.add(trunk,leaves);
 return{meta,ground,roads,buildings,nearest,free,windowMaterials,photoMaterials};
}
